def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    rem = 100 - n
    if rem <= 0:
        return 'C'
    if rem == 1:
        return 'D'

    me = [m for (m, o) in history]
    op = [o for (m, o) in history]
    my_d = 0
    opp_d = 0
    for i in range(n):
        if me[i] == 'D':
            my_d += 1
        if op[i] == 'D':
            opp_d += 1

    last_me = me[-1]
    last_opp = op[-1]

    start = n - 10
    if start < 0:
        start = 0
    recent_len = n - start
    recent_coop = 0
    for i in range(start, n):
        if op[i] == 'C':
            recent_coop += 1
    recent_d = recent_len - recent_coop
    r10_rate = recent_d / recent_len if recent_len else 0.0
    d_rate = opp_d / n if n else 0.0

    opD_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opD_streak += 1
        else:
            break

    unprov_streak = 0
    for i in range(n - 1, 0, -1):
        if me[i - 1] == 'C' and op[i] == 'D':
            unprov_streak += 1
        else:
            break

    if my_d == 0 and last_opp == 'D':
        if opp_d <= 4:
            return 'C'
        return 'D'

    if my_d == 0 and last_me == 'C' and last_opp == 'C':
        if 1 <= opp_d <= 4 and n <= 30 and recent_coop >= 6:
            return 'D'

    if my_d > 0 and unprov_streak >= 2:
        return 'D'

    prev_c = 0
    c_after_c = 0
    prev_d = 0
    c_after_d = 0
    tft_match_count = 0
    unprov_count = 0

    for i in range(1, n):
        pm = me[i - 1]
        co = op[i]
        if co == pm:
            tft_match_count += 1
        if pm == 'C':
            prev_c += 1
            if co == 'C':
                c_after_c += 1
            else:
                unprov_count += 1
        else:
            prev_d += 1
            if co == 'C':
                c_after_d += 1

    if n > 1:
        unprov_rate = unprov_count / prev_c if prev_c else 0.0
        tft_match = tft_match_count / (n - 1)
    else:
        unprov_rate = 0.0
        tft_match = 1.0

    tft_like = n >= 6 and tft_match >= 0.70 and unprov_rate <= 0.05

    if my_d > 0 and (d_rate >= 0.35 or r10_rate >= 0.45):
        if not tft_like and (unprov_rate >= 0.10 or r10_rate >= 0.40):
            return 'D'

    if (r10_rate >= 0.70 or d_rate >= 0.55 or opD_streak >= 7) and not tft_like:
        return 'D'

    if my_d == 0 and rem <= 6 and last_me == 'C' and last_opp == 'C':
        if opp_d <= 4 and recent_coop >= 9:
            return 'D'

    if prev_c == 0:
        if n <= 5:
            qC = 0.7
        else:
            qC = 1.0 - d_rate
            if qC < 0.15:
                qC = 0.15
    else:
        qC = (c_after_c + 2.0) / (prev_c + 3.0)

    if prev_d == 0:
        qD = 0.2
    else:
        qD = (c_after_d + 1.0) / (prev_d + 2.0)

    if qC > 1.0:
        qC = 1.0
    if qC < 0.0:
        qC = 0.0
    if qD > 1.0:
        qD = 1.0
    if qD < 0.0:
        qD = 0.0

    vc = 0.0
    vd = 0.0
    for _ in range(rem - 1):
        nvc = 3.0 * qC + vc
        alt = 1.0 + 4.0 * qC + vd
        if alt > nvc:
            nvc = alt
        nvd = 3.0 * qD + vc
        alt = 1.0 + 4.0 * qD + vd
        if alt > nvd:
            nvd = alt
        vc = nvc
        vd = nvd

    if last_me == 'C':
        valC = 3.0 * qC + vc
        valD = 1.0 + 4.0 * qC + vd
    else:
        valC = 3.0 * qD + vc
        valD = 1.0 + 4.0 * qD + vd

    if valD > valC:
        return 'D'
    return 'C'
